import urllib.request
import json
import os
import subprocess

def split_text(text, limit=4000):
    chunks = []
    while len(text) > limit:
        # Find the last period within the limit to split at a sentence boundary
        split_index = text.rfind('.', 0, limit)
        if split_index == -1:
            split_index = limit
        else:
            split_index += 1 # Include the period
        chunks.append(text[:split_index].strip())
        text = text[split_index:]
    if text:
        chunks.append(text.strip())
    return chunks

def text_to_speech(text, output_file):
    url = "https://api.openai.com/v1/audio/speech"
    api_key = os.environ.get('OPENAI_API_KEY')
    if not api_key:
        print("Error: OPENAI_API_KEY not found in environment.")
        return False

    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json"
    }
    data = {
        "model": "tts-1",
        "input": text,
        "voice": "alloy"
    }

    req = urllib.request.Request(url, data=json.dumps(data).encode(), headers=headers)
    try:
        with urllib.request.urlopen(req) as response:
            with open(output_file, "wb") as f:
                f.write(response.read())
        return True
    except Exception as e:
        print(f"Error calling OpenAI API: {e}")
        return False

def main():
    with open('essays.txt', 'r') as f:
        full_text = f.read()

    chunks = split_text(full_text)
    print(f"Split text into {len(chunks)} chunks.")

    chunk_files = []
    for i, chunk in enumerate(chunks):
        chunk_file = f"chunk_{i}.mp3"
        print(f"Converting chunk {i+1}/{len(chunks)}...")
        if text_to_speech(chunk, chunk_file):
            chunk_files.append(chunk_file)
        else:
            print(f"Failed to convert chunk {i}")
            return

    if chunk_files:
        # Create a concat file for ffmpeg
        with open('concat.txt', 'w') as f:
            for cf in chunk_files:
                f.write(f"file '{cf}'\n")

        print("Merging chunks...")
        try:
            subprocess.run(['ffmpeg', '-f', 'concat', '-safe', '0', '-i', 'concat.txt', '-c', 'copy', '/root/audiobook.mp3', '-y'], check=True)
            print("Audiobook created successfully at /root/audiobook.mp3")
        except subprocess.CalledProcessError as e:
            print(f"Error merging files with ffmpeg: {e}")

        # Cleanup
        for cf in chunk_files:
            os.remove(cf)
        os.remove('concat.txt')

if __name__ == "__main__":
    main()

